package com.wams.quotation.dto;import com.wams.quotation.*;import java.math.BigDecimal;import java.time.*;
public record QuotationResponse(Long id,Long projectId,String projectName,Long functionId,String functionName,Long vendorId,String vendorName,String service,LocalDate deadline,QuotationStatus status,BigDecimal amount,String description,Instant submittedAt,Instant decidedAt){public static QuotationResponse from(QuotationRequest q){return new QuotationResponse(q.getId(),q.getProject().getId(),q.getProject().getProjectName(),q.getFunction()==null?null:q.getFunction().getId(),q.getFunction()==null?null:q.getFunction().getName(),q.getVendor().getId(),q.getVendor().getBusinessName(),q.getService(),q.getDeadline(),q.getStatus(),q.getAmount(),q.getDescription(),q.getSubmittedAt(),q.getDecidedAt());}}
